using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides the HttpClient
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/weather?city={Uri.EscapeDataString(city)}",
            cancellationToken);

        return response is null
            ? $"No weather data found for '{city}'."
            : $"{city}: {response.Temperature}°F, {response.Condition}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetExtendedForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-7)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse[]>(
            $"/forecast?city={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        if (response is null or { Length: 0 })
            return $"No forecast data for '{city}'.";

        var lines = response.Select(r => $"  {r.Date}: {r.Temperature}°F, {r.Condition}");
        return $"Forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

public sealed record WeatherResponse
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; init; }

    [JsonPropertyName("condition")]
    public string Condition { get; init; } = "";

    [JsonPropertyName("date")]
    public string Date { get; init; } = "";
}

